    // -------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------
    .reg .u64 %A, %B, %C;
    .reg .u32 %M, %N, %K;
    ld.param.u64 %A, [A_ptr];
    ld.param.u64 %B, [B_ptr];
    ld.param.u64 %C, [C_ptr];
    ld.param.u32 %M, [M];
    ld.param.u32 %N, [N];
    ld.param.u32 %K, [K];

    // -------------------------------------------------
    // Compute global thread coordinates
    // -------------------------------------------------
    .reg .u32 %tid_x, %tid_y;
    .reg .u32 %block_x, %block_y;
    .reg .u32 %row, %col;

    mov.u32 %tid_x, %tid.x;
    mov.u32 %tid_y, %tid.y;
    mov.u32 %block_x, %ctaid.x;
    mov.u32 %block_y, %ctaid.y;

    // col = block_x * blockDim.x + tid_x
    // row = block_y * blockDim.y + tid_y
    mad.lo.u32 %col, %block_x, %ntid.x, %tid_x;
    mad.lo.u32 %row, %block_y, %ntid.y, %tid_y;

    // -------------------------------------------------
    // Boundary check
    // -------------------------------------------------
    .pred %p_out_of_bounds;
    setp.ge.u32 %p_out_of_bounds, %row, %M;
    @%p_out_of_bounds bra DONE;
    setp.ge.u32 %p_out_of_bounds, %col, %N;
    @%p_out_of_bounds bra DONE;

    // -------------------------------------------------
    // Accumulator (float32)
    // -------------------------------------------------
    .reg .f32 %sum;
    mov.f32 %sum, 0f00000000;    // 0.0f

    // -------------------------------------------------
    // Loop over K dimension
    // -------------------------------------------------
    .reg .u32 %k;
    mov.u32 %k, 0;

LOOP_K:
    setp.ge.u32 %p_out_of_bounds, %k, %K;
    @%p_out_of_bounds bra END_LOOP;

    // Compute address of A[row, k]
    .reg .u64 %addrA;
    mul.lo.u64 %addrA, %row, %K;          // row * K
    add.u64 %addrA, %addrA, %k;           // row*K + k
    mul.lo.u64 %addrA, %addrA, 2;         // * sizeof(fp16)
    add.u64 %addrA, %A, %addrA;           // global address

    // Compute address of B[k, col]
    .reg .u64 %addrB;
    mul.lo.u64 %addrB, %k, %N;            // k * N
    add.u64 %addrB, %addrB, %col;         // k*N + col
    mul.lo.u64 %addrB, %addrB, 2;         // * sizeof(fp16)
    add.u64 %addrB, %B, %addrB;           // global address

    // Load fp16 values
    .reg .f16 %a_f16, %b_f16;
    ld.global.f16 %a_f16, [%addrA];
    ld.global.f16 %b_f16, [%addrB];

    // Convert to fp32
    .reg .f32 %a_f32, %b_f32;
    cvt.f32.f16 %a_f32, %a_f16;
    cvt.f32.f16 %b_f32, %b_f16;

    // FMA: sum += a * b
    fma.rn.f32 %sum, %a_f32, %b_f32, %sum;

    // k++
    add.u32 %k, %k, 1;
    bra LOOP_K;

