    // Write result back to C[row, col] (fp16)
    // -------------------------------------------------
    .reg .u64 %addrC;
    mul.lo.u64 %addrC, %row, %N;          // row * N
    add.u64 %addrC, %addrC, %col;         // row*N + col
    mul.lo.u64 %addrC, %addrC, 2;         // * sizeof(fp16)
    add.u64 %addrC, %C, %addrC;           // global address

    // Convert accumulator to fp16 (round‑to‑nearest‑even)
    .reg .f16 %c_f16;
    cvt.rn.f16.f32 %c_f16, %sum;
    st.global.f16 [%addrC], %c_f16;

